import React from 'react';
export default function Docs(){
  return (
    <div>
      <h2>Documentación</h2>
      <p>Ejemplos y líneas de profundización:</p>
      <ul>
        <li><b>IA:</b> Implementar un pequeño modelo o integrar una API de ML.</li>
        <li><b>Ciberseguridad:</b> Autenticación, almacenamiento seguro de tokens.</li>
        <li><b>Repositorio:</b> Estructura de GitHub y README con instrucciones.</li>
      </ul>
    </div>
  );
}
